300	    public LocalDate getBirthDate() {
301	        return this.birthDate;
302	    }
303	
304	    public void setBirthDate(LocalDate birthDate) {
305	        this.birthDate = birthDate;
306	    }
307	
308	    /**
309	     * Return the owner's age band derived from the birth date, computed against the
310	     * registration date: {@code 'MINOR'} when under 18, {@code 'ADULT'} when 18 to
311	     * 64 inclusive, and {@code 'SENIOR'} when 65 or older. Returns {@code null} when
312	     * either the birth date or the registration date is not set.
313	     */
314	    public String getAgeBand() {
315	        if (this.birthDate == null || this.registrationDate == null) {
316	            return null;
317	        }
318	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
319	        if (age < 18) {
320	            return "MINOR";
321	        }
322	        if (age < 65) {
323	            return "ADULT";
324	        }
325	        return "SENIOR";
326	    }
