328	    public String getPostcode() {
329	        return this.postcode;
330	    }
331	
332	    public void setPostcode(String postcode) {
333	        this.postcode = postcode;
334	    }
335	
336	    /**
337	     * Whether this owner's postcode is valid for its city. A {@code null} postcode
338	     * is always valid (postcode is optional). When present, a postcode is valid if
339	     * the city has no known region, or if it is four digits falling within the
340	     * inclusive range for the city's region ({@code Sydney -> NSW 2000-2099},
341	     * {@code Melbourne -> VIC 3000-3099}, {@code Brisbane -> QLD 4000-4099}).
342	     */
343	    public boolean isPostcodeValidForCity() {
344	        if (this.postcode == null) {
345	            return true;
346	        }
347	        String region = CITY_REGION.get(this.city);
348	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
349	        if (range == null) {
350	            return true;
351	        }
352	        if (!this.postcode.matches("^[0-9]{4}$")) {
353	            return false;
354	        }
355	        int value = Integer.parseInt(this.postcode);
356	        return value >= range[0] && value <= range[1];
357	    }
358	
359	    public String getMemberId() {
360	        return this.memberId;
361	    }
362	
363	    public void setMemberId(String memberId) {
364	        this.memberId = memberId;
365	    }
366	
367	    /**
368	     * Return the owner's fiscal year, formatted {@code 'FY<YY>'} where {@code YY}
369	     * is the last two digits of the fiscal year derived from the (business-day
370	     * adjusted) registration date. The fiscal year starts on 1 July and is named
371	     * after the calendar year in which it ends, so a registration date on or after
372	     * 1 July belongs to the fiscal year ending the following calendar year (for
373	     * example {@code 2026-08-14 -> 'FY27'}), while a date before 1 July belongs to
374	     * the fiscal year ending in that same calendar year. Returns {@code null} when
375	     * the registration date is not set.
376	     */
377	    public String getFiscalYear() {
378	        Integer fiscalYear = fiscalYearOf(this.registrationDate);
379	        if (fiscalYear == null) {
380	            return null;
381	        }
382	        return String.format("FY%02d", fiscalYear % 100);
383	    }
384	
385	    /**
386	     * Return the fiscal year (the calendar year in which the fiscal year ends) that
387	     * the given date falls in, where the fiscal year starts on 1 July, or
388	     * {@code null} when the date is {@code null}.
389	     */
390	    private static Integer fiscalYearOf(LocalDate date) {
391	        if (date == null) {
392	            return null;
393	        }
394	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
395	    }
396	
397	    public String getHouseholdId() {
398	        return this.householdId;
399	    }
400	
401	    public void setHouseholdId(String householdId) {
402	        this.householdId = householdId;
403	    }
404	
405	    public Integer getNamesakeCount() {
406	        return this.namesakeCount;
407	    }
408	
409	    /**
410	     * Return the owner's membership points, the raw score from which the
411	     * membership level is derived. Starting at {@code 0}, add {@code 2} when an
412	     * email address is present, {@code 1} when the owner has no namesakes
413	     * (namesake count is {@code 0}), {@code 2} for a household of {@code 3} or
414	     * more, and {@code 3} when the owner's tenure (the number of fiscal years
415	     * elapsed since the registration date, the fiscal year starting on 1 July) is
416	     * at least {@code 1}.
417	     */
418	    public Integer getMembershipPoints() {
419	        int points = 0;
420	        boolean hasEmail = this.email != null && !this.email.isBlank();
421	        if (hasEmail) {
422	            points += 2;
423	        }
424	        if (this.namesakeCount != null && this.namesakeCount == 0) {
425	            points += 1;
426	        }
427	        if (this.householdSize != null && this.householdSize >= 3) {
428	            points += 2;
429	        }
430	        Integer registrationFiscalYear = fiscalYearOf(this.registrationDate);
431	        if (registrationFiscalYear != null) {
432	            int elapsedFiscalYears = fiscalYearOf(LocalDate.now()) - registrationFiscalYear;
433	            if (elapsedFiscalYears >= 1) {
434	                points += 3;
435	            }
436	        }
437	        return points;
438	    }
439	
440	    /**
441	     * Return the owner's membership level, a number from {@code 1} to {@code 4},
442	     * derived from {@link #getMembershipPoints()}: {@code 1} for {@code 0-1}
443	     * points, {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and
444	     * {@code 4} for {@code 6} or more. When a {@code membershipLevelCap} is set,
445	     * the derived level is capped at it (a level higher than the cap is lowered to
446	     * the cap); the cap records one above the maximum level among the owner's
447	     * household members at creation time.
448	     */
449	    public Integer getMembershipLevel() {
450	        int points = getMembershipPoints();
451	        int level;
452	        if (points >= 6) {
453	            level = 4;
454	        }
455	        else if (points >= 4) {
456	            level = 3;
457	        }
458	        else if (points >= 2) {
459	            level = 2;
460	        }
461	        else {
462	            level = 1;
463	        }
464	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
465	            return this.membershipLevelCap;
466	        }
467	        return level;
468	    }
469	
470	    public Integer getMembershipLevelCap() {
471	        return this.membershipLevelCap;
472	    }
473	
474	    public void setMembershipLevelCap(Integer membershipLevelCap) {
475	        this.membershipLevelCap = membershipLevelCap;
476	    }
477	
478	    public void setNamesakeCount(Integer namesakeCount) {
479	        this.namesakeCount = namesakeCount;
480	    }
481	
482	    public Integer getHouseholdSize() {
483	        return this.householdSize;
484	    }
485	
486	    public void setHouseholdSize(Integer householdSize) {
487	        this.householdSize = householdSize;
488	    }
489	
490	    /**
491	     * Whether this owner, when created, softly matched an existing owner by
492	     * sharing the same last name and postcode but with a different telephone.
493	     * Such an owner is still created; the flag surfaces the likely duplication.
494	     */
495	    public Boolean getPossibleDuplicate() {
496	        return this.possibleDuplicate;
497	    }
498	
499	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
500	        this.possibleDuplicate = possibleDuplicate;
501	    }
502	
503	    /**
504	     * The id of the existing owner this owner softly matched on last name and
505	     * postcode (with a different telephone), or {@code null} when there is no
506	     * such match.
507	     */
508	    public Integer getPossibleDuplicateOf() {
509	        return this.possibleDuplicateOf;
510	    }
511	
512	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
513	        this.possibleDuplicateOf = possibleDuplicateOf;
514	    }
515	
516	    /**
517	     * Whether this owner has been soft-deleted. A newly created owner is not
518	     * deleted; {@code DELETE /api/owners/{id}} sets this flag rather than removing
519	     * the row, and a flagged owner is ignored by the create endpoint's duplicate
520	     * and identity checks.
521	     */
522	    public boolean isDeleted() {
523	        return this.deleted;
524	    }
525	
526	    public void setDeleted(boolean deleted) {
527	        this.deleted = deleted;
528	    }
529	
530	    /**
531	     * Whether more than 80 owners had already been registered on this owner's
532	     * registration day at the time it was created, flagging a bulk-signup surge.
533	     */
534	    public Boolean getBulkSignupWarning() {
535	        return this.bulkSignupWarning;
536	    }
537	
538	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
539	        this.bulkSignupWarning = bulkSignupWarning;
540	    }
541	
542	    /**
543	     * Whether this owner's city already held between 40 and 49 owners at the time
544	     * it was created, flagging that the city is approaching the per-city capacity
545	     * limit of 50 (at which further creates are rejected).
546	     */
547	    public Boolean getCapacityWarning() {
548	        return this.capacityWarning;
549	    }
550	
551	    public void setCapacityWarning(Boolean capacityWarning) {
552	        this.capacityWarning = capacityWarning;
553	    }
554	
555	    /**
556	     * Return the owner's locality (region), preferring the postcode: when the
557	     * postcode is present and falls within a known region's inclusive range
558	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), that
559	     * region is returned. Otherwise the value falls back to the fixed
560	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
561	     * {@code Brisbane -> QLD}), or {@code 'UNKNOWN'} when the city is not in the
562	     * table. This yields the same region for known cities but disambiguates
563	     * cities that share a name.
564	     */
565	    public String getLocality() {
566	        String regionFromPostcode = regionForPostcode();
567	        if (regionFromPostcode != null) {
568	            return regionFromPostcode;
569	        }
570	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
571	    }
572	
573	    /**
574	     * Return the owner's IANA timezone, derived from the locality/region via the
575	     * fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
576	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}), or
577	     * {@code null} when the region is not in the table.
578	     */
579	    public String getTimezone() {
580	        return REGION_TIMEZONE.get(getLocality());
581	    }
582	
583	    /**
584	     * Look up the region whose inclusive postcode range contains this owner's
585	     * postcode, or {@code null} when the postcode is absent, malformed, or in no
586	     * known range.
587	     */
588	    private String regionForPostcode() {
589	        if (this.postcode == null || !this.postcode.matches("^[0-9]{4}$")) {
590	            return null;
591	        }
592	        int value = Integer.parseInt(this.postcode);
593	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
594	            int[] range = entry.getValue();
595	            if (value >= range[0] && value <= range[1]) {
596	                return entry.getKey();
597	            }
598	        }
599	        return null;
600	    }
601	
602	    /**
603	     * Return the owner's preferred contact channel, derived from the stored
604	     * contact details: {@code 'EMAIL'} when an email address is present,
605	     * otherwise {@code 'PHONE'}.
606	     */
607	    public String getContactPreference() {
608	        boolean hasEmail = this.email != null && !this.email.isBlank();
609	        return hasEmail ? "EMAIL" : "PHONE";
610	    }
611	
612	    /**
613	     * Return the owner's marketing segment, formatted {@code '<TIER>_<AREA>'}.
614	     * {@code TIER} is {@code 'PREMIUM'} when the {@link #getMembershipLevel()
615	     * membership level} is {@code 3} or more, otherwise {@code 'STANDARD'}.
616	     * {@code AREA} is {@code 'METRO'} when the {@link #getLocality() locality}
617	     * is a known region ({@code NSW}, {@code VIC} or {@code QLD}), otherwise
618	     * {@code 'REGIONAL'}.
619	     */
620	    public String getOwnerSegment() {
621	        Integer membershipLevel = getMembershipLevel();
622	        String tier = (membershipLevel != null && membershipLevel >= 3) ? "PREMIUM" : "STANDARD";
623	        String area = REGION_TIMEZONE.containsKey(getLocality()) ? "METRO" : "REGIONAL";
624	        return tier + "_" + area;
625	    }
626	
627	    /**
628	     * Return the owner's derived identity key, which consolidates all duplicate
629	     * detection into a single value: the SHA-256 digest, rendered as 64 lower-case
630	     * hex characters, of {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'}.
631	     * The telephone and email are already stored in their normalized (E.164 /
632	     * lower-cased) forms; a missing email contributes an empty segment and the last
633	     * name is reduced to its Soundex code. A create is rejected only when a new
634	     * owner's whole identity key equals an existing owner's.
635	     */
636	    public String getIdentityKey() {
637	        String telephonePart = this.telephone == null ? "" : this.telephone;
638	        String emailPart = (this.email == null) ? "" : this.email.toLowerCase(Locale.ROOT);
639	        String soundexPart = soundex(getLastName());
640	        String key = telephonePart + "|" + emailPart + "|" + soundexPart;
641	        try {
642	            byte[] digest = MessageDigest.getInstance("SHA-256")
643	                .digest(key.getBytes(StandardCharsets.UTF_8));
644	            StringBuilder sb = new StringBuilder(digest.length * 2);
645	            for (byte b : digest) {
646	                sb.append(String.format("%02x", b));
647	            }
648	            return sb.toString();
649	        }
650	        catch (NoSuchAlgorithmException e) {
651	            throw new IllegalStateException(e);
652	        }
653	    }
654	
655	    /**
656	     * Compute the American Soundex code of the given name: its first letter followed
657	     * by three digits derived from the remaining consonants (vowels act as separators,
658	     * {@code H} and {@code W} are transparent, and adjacent equal codes collapse),
659	     * zero-padded and truncated to four characters. Returns an empty string when the
660	     * name is {@code null} or holds no letters.
661	     */
662	    public static String soundex(String name) {
663	        if (name == null) {
664	            return "";
665	        }
666	        StringBuilder letters = new StringBuilder();
667	        for (int i = 0; i < name.length(); i++) {
668	            char c = name.charAt(i);
669	            if (Character.isLetter(c)) {
670	                letters.append(Character.toUpperCase(c));
671	            }
672	        }
673	        if (letters.length() == 0) {
674	            return "";
675	        }
676	        StringBuilder code = new StringBuilder();
677	        code.append(letters.charAt(0));
678	        char prevDigit = soundexDigit(letters.charAt(0));
679	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
680	            char c = letters.charAt(i);
681	            if (c == 'H' || c == 'W') {
682	                continue;
683	            }
684	            char digit = soundexDigit(c);
685	            if (digit != '0' && digit != prevDigit) {
686	                code.append(digit);
687	            }
688	            prevDigit = digit;
689	        }
690	        while (code.length() < 4) {
691	            code.append('0');
692	        }
693	        return code.toString();
694	    }
695	
696	    private static char soundexDigit(char c) {
697	        switch (c) {
698	            case 'B': case 'F': case 'P': case 'V':
699	                return '1';
700	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
701	                return '2';
702	            case 'D': case 'T':
703	                return '3';
704	            case 'L':
705	                return '4';
706	            case 'M': case 'N':
707	                return '5';
708	            case 'R':
709	                return '6';
710	            default:
711	                return '0';
712	        }
713	    }
714	
715	    protected Set<Pet> getPetsInternal() {
716	        if (this.pets == null) {
717	            this.pets = new HashSet<>();
718	        }
719	        return this.pets;
720	    }
721	
722	    protected void setPetsInternal(Set<Pet> pets) {
723	        this.pets = pets;
724	    }
725	
726	    public List<Pet> getPets() {
727	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
728	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
729	        return Collections.unmodifiableList(sortedPets);
730	    }
731	
732	    public void setPets(List<Pet> pets) {
733	        this.pets = new HashSet<>(pets);
734	    }
735	
736	    public void addPet(Pet pet) {
737	        getPetsInternal().add(pet);
738	        pet.setOwner(this);
739	    }
740	
741	    /**
742	     * Return the Pet with the given name, or null if none found for this Owner.
743	     *
744	     * @param name to test
745	     * @return true if pet name is already in use
746	     */
747	    public Pet getPet(String name) {
748	        return getPet(name, false);
749	    }
750	
751	    /**
752	     * Return the Pet with the given name, or null if none found for this Owner.
753	     *
754	     * @param name to test
755	     * @return true if pet name is already in use
756	     */
757	    public Pet getPet(String name, boolean ignoreNew) {
758	        name = name.toLowerCase();
759	        for (Pet pet : getPetsInternal()) {
760	            if (!ignoreNew || !pet.isNew()) {
761	                String compName = pet.getName();
762	                compName = compName.toLowerCase();
763	                if (compName.equals(name)) {
764	                    return pet;
765	                }
766	            }
767	        }
768	        return null;
769	    }
770	
771	    public Pet getPet(Integer petId) {
772	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
773	    }
774	
775	    @Override
776	    public String toString() {
777	        return new ToStringCreator(this)
778	
779	            .append("id", this.getId())
780	            .append("new", this.isNew())
781	            .append("lastName", this.getLastName())
782	            .append("firstName", this.getFirstName())
783	            .append("address", this.address)
784	            .append("city", this.city)
785	            .append("telephone", this.telephone)
786	            .append("email", this.email)
787	            .toString();
788	    }
789	}
